package plugin

import (
	"bytes"
	"sync"
)

// Log-capture bounds (plugin-admin-surfaces D3): a 256-line tail per plugin,
// each line clamped to 2 KiB — 256 × 2 KiB per plugin bounds the capture
// regardless of how chatty the subprocess stderr is.
const (
	logRingLines    = 256
	logLineMaxBytes = 2 * 1024
)

// logRing is the bounded per-plugin stderr capture (plugin-admin-surfaces
// D3): a fixed-capacity line ring — the tail wins, oldest lines drop first —
// fed by an io.Writer that reassembles partial chunks into lines (go-plugin
// delivers the subprocess stderr in arbitrary chunks, never guaranteed
// line-aligned). Each line is clamped to logLineMaxBytes; an over-long line is
// stored truncated and never breaks the buffer. A trailing fragment with no
// newline stays pending until its newline arrives (a log tail without the
// subprocess's final unterminated line is still a correct tail).
type logRing struct {
	mu    sync.Mutex
	slots [logRingLines]string
	head  int // index of the oldest retained line
	count int
	// pending holds the in-progress line's bytes (no newline seen yet),
	// clamped as it grows so an unterminated stream cannot grow it unbounded.
	pending string
}

// Write consumes one stderr chunk, splitting it into newline-delimited lines.
// It always reports the full chunk consumed: capture is observation only, and
// a short write or error would fail the go-plugin stderr copier.
func (r *logRing) Write(p []byte) (int, error) {
	total := len(p)
	r.mu.Lock()
	defer r.mu.Unlock()
	for {
		i := bytes.IndexByte(p, '\n')
		if i < 0 {
			r.appendPending(p)
			return total, nil
		}
		r.appendPending(p[:i])
		r.push(r.pending)
		r.pending = ""
		p = p[i+1:]
	}
}

// appendPending extends the in-progress line up to the clamp; bytes past the
// clamp are dropped, so a stored line is the line's FIRST logLineMaxBytes.
func (r *logRing) appendPending(p []byte) {
	if len(p) == 0 || len(r.pending) >= logLineMaxBytes {
		return
	}
	if room := logLineMaxBytes - len(r.pending); len(p) > room {
		p = p[:room]
	}
	r.pending += string(p)
}

// push retires one completed line into the ring, overwriting the oldest when
// full (the head index rotates instead of shifting the buffer).
func (r *logRing) push(line string) {
	if r.count == logRingLines {
		r.slots[r.head] = line
		r.head = (r.head + 1) % logRingLines
		return
	}
	r.slots[(r.head+r.count)%logRingLines] = line
	r.count++
}

// lines returns the retained tail oldest-first, as a fresh slice the caller
// may mutate freely — the ring's own state is never exposed (copy-on-read).
func (r *logRing) lines() []string {
	r.mu.Lock()
	defer r.mu.Unlock()
	out := make([]string, r.count)
	for i := 0; i < r.count; i++ {
		out[i] = r.slots[(r.head+i)%logRingLines]
	}
	return out
}
